","import React, { useState, useEffect, useCallback } from "react";
import { Button } from "@servicenow/react-components/Button";
import "./styles.css";
import PendingList from "./components/PendingList";
import AllInspectionsList from "./components/AllInspectionsList";
import InspectionDetail from "./components/InspectionDetail";
import DispositionsList from "./components/DispositionsList";
import DispositionDetail from "./components/DispositionDetail";
import AlertsList from "./components/AlertsList";
import AlertDetail from "./components/AlertDetail";
import BatchesList from "./components/BatchesList";
import BatchDetail from "./components/BatchDetail";
import MaterialsList from "./components/MaterialsList";
import MaterialDetail from "./components/MaterialDetail";

interface ViewState {
 view: string;
 recordId: string | null;
 from: string | null;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "pending",
 recordId: params.get("id") || null,
 from: params.get("from") || null,
 };
}

const DETAIL_TO_TAB: Record<string, string> = {
 "disposition-detail": "dispositions",
 "alert-detail": "alerts",
 "batch-detail": "batches",
 "material-detail": "materials",
};

const TABS = [
 { id: "pending", label: "Pending" },
 { id: "all-insp", label: "All Insp." },
 { id: "dispositions", label: "Dispositions" },
 { id: "alerts", label: "Alerts" },
 { id: "batches", label: "Batches" },
 { id: "materials", label: "Materials" },
];

export default function App() {
 const [vs, setVs] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const h = () => setVs(getViewFromUrl());
 window.addEventListener("popstate", h);
 return () => window.removeEventListener("popstate", h);
 }, []);

 const nav = useCallback(
 (view: string, id?: string | null, from?: string | null) => {
 const p = new URLSearchParams({ view });
 if (id) p.set("id", id);
 if (from) p.set("from", from);
 const rel = `${window.location.pathname}?${p}`;
 const title = `Quality - ${view}`;
 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop(
 "magellanNavigator.permalink.set",
 { relativePath: rel, title }
 );
 }
 window.history.pushState({ view, id, from }, "", rel);
 document.title = title;
 setVs({ view, recordId: id || null, from: from || null });
 },
 []
 );

 const { view, recordId, from } = vs;

 const activeTab =
 view === "inspection-detail"
 ? from || "pending"
 : DETAIL_TO_TAB[view] || view;

 const renderView = () => {
 if (view === "inspection-detail" && recordId) {
 return (
 <InspectionDetail
 id={recordId}
 onBack={() => nav(from || "pending")}
 />
 );
 }
 if (view === "disposition-detail" && recordId) {
 return (
 <DispositionDetail id={recordId} onBack={() => nav("dispositions")} />
 );
 }
 if (view === "alert-detail" && recordId) {
 return <AlertDetail id={recordId} onBack={() => nav("alerts")} />;
 }
 if (view === "batch-detail" && recordId) {
 return <BatchDetail id={recordId} onBack={() => nav("batches")} />;
 }
 if (view === "material-detail" && recordId) {
 return <MaterialDetail id={recordId} onBack={() => nav("materials")} />;
 }
 if (view === "all-insp") {
 return (
 <AllInspectionsList
 onSelect={(id) => nav("inspection-detail", id, "all-insp")}
 />
 );
 }
 if (view === "dispositions") {
 return (
 <DispositionsList
 onSelect={(id) => nav("disposition-detail", id)}
 />
 );
 }
 if (view === "alerts") {
 return <AlertsList onSelect={(id) => nav("alert-detail", id)} />;
 }
 if (view === "batches") {
 return <BatchesList onSelect={(id) => nav("batch-detail", id)} />;
 }
 if (view === "materials") {
 return <MaterialsList onSelect={(id) => nav("material-detail", id)} />;
 }
 return (
 <PendingList
 onSelect={(id) => nav("inspection-detail", id, "pending")}
 />
 );
 };

 return (
 <div className="qa-shell">
 <div className="qa-header">Quality Staff</div>
 <div className="qa-content">{renderView()}</div>
 <div className="qa-bottom-nav">
 {TABS.map((tab) => (
 <div
 key={tab.id}
 className={`qa-nav-btn ${activeTab === tab.id ? "active" : ""}`}
 >
 <Button
 label={tab.label}
 size="sm"
 variant={activeTab === tab.id ? "primary" : "secondary"}
 onClick={() => nav(tab.id)}
 />
 </div>
 ))}
 </div>
 </div>
 );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")!).render(<App />);
